import{_ as t,o as r,c as o,a2 as d}from"./chunks/framework.BbQUUm7J.js";const h=JSON.parse('{"title":"Honesty Matrix — Live vs. Simulated","description":"","frontmatter":{},"headers":[],"relativePath":"reference/honesty-matrix.md","filePath":"reference/honesty-matrix.md","lastUpdated":1794940900000}'),a={name:"reference/honesty-matrix.md"};function n(s,e,i,c,l,u){return r(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="honesty-matrix-—-live-vs-simulated" tabindex="-1">Honesty Matrix — Live vs. Simulated <a class="header-anchor" href="#honesty-matrix-—-live-vs-simulated" aria-label="Permalink to &quot;Honesty Matrix — Live vs. Simulated&quot;">​</a></h1><p>Every execution surface in this CLI is <strong>labeled at runtime</strong>. This table is the authoritative summary; where code and marketing ever disagree, the runtime label wins.</p><table tabindex="0"><thead><tr><th>Surface</th><th>Status</th><th>Notes</th></tr></thead><tbody><tr><td>Hyperliquid market data (<code>market</code>, <code>hyperliquid markets/status</code>)</td><td><strong>LIVE</strong></td><td>Real <code>/info</code> responses from Hyperliquid validators</td></tr><tr><td>Live trade terminal (<code>furlpay live &lt;SYM&gt;</code>)</td><td><strong>LIVE (data) + LOCAL (render)</strong></td><td>Real Hyperliquid WebSocket (<code>l2Book</code> + <code>trades</code>) through the streaming state machines: feed regression freezes the book (never renders stale as current), disconnect renders DISCONNECTED — never a fake book. Gauges (OBI, micro-price, rolling VPIN, optional GLFT quotes) computed on the live feed. The terminal NEVER places, signs or broadcasts: [Space] PANIC prints the signed kill-switch command and only spawns it with <code>--allow-panic</code> (that command still runs the risk engine and fails closed without a signer)</td></tr><tr><td>Transaction verification (<code>tx verify</code>)</td><td><strong>LIVE (lookup)</strong></td><td>Real Horizon <code>GET /transactions/{hash}</code>; distinguishes confirmed-success / confirmed-failed / not-found / invalid / unavailable; explicitly an API lookup, never claimed as cryptographic re-verification</td></tr><tr><td>Testnet faucet (<code>faucet</code>)</td><td><strong>LIVE</strong></td><td>Real Friendbot funding on testnet/futurenet only (mainnet refused); <code>FUNDED</code> requires the Friendbot&#39;s own successful response + independent Horizon balance check</td></tr><tr><td>Config validation (<code>config validate</code>)</td><td>LOCAL</td><td>Structural checks on the local config; no network calls</td></tr><tr><td>Diagnostics (<code>doctor</code>)</td><td>LIVE checks</td><td>Real connectivity/registry checks; exits non-zero when the API liveness check fails</td></tr><tr><td>HLP vault stats (<code>earn hlp stats</code>)</td><td><strong>LIVE</strong></td><td>Equity/APY/PnL derived from live <code>vaultDetails</code>; unreported fields → unavailable, never fabricated</td></tr><tr><td>HLP deposit / withdraw</td><td><strong>LIVE (signed)</strong></td><td>Real EIP-712 <code>vaultTransfer</code> actions; fail closed without <code>HYPERLIQUID_PRIVATE_KEY</code>/<code>ETH_PRIVATE_KEY</code>; missing tx hash → <code>PENDING_CONFIRMATION</code>, never a synthetic id</td></tr><tr><td>Hyperliquid perp execution (<code>hyperliquid trade</code>)</td><td><strong>LIVE (signed)</strong></td><td>Requires configured signer; pre-trade risk engine enforced <strong>fail-closed</strong> — asset-metadata, L2-book and clearinghouse-state failures refuse the order instead of skipping the guard; margin check runs on live account state; scaled-BigInt money math throughout</td></tr><tr><td>Pre-trade USDC peg guardrail</td><td><strong>LIVE</strong> (feed ingestion)</td><td>Every pre-trade evaluation ingests USDC/USD (CoinGecko default, <code>FURLPAY_USDC_PEG_FEED_URL</code> override, ≥30s cadence, https-only); &gt;25 bps drift halts risk-increasing orders with 5-min recovery hysteresis. A feed outage is never depeg evidence and never recovery evidence — a halt in force stays until real data proves recovery; a no-data pass carries an explicit <code>PEG_FEED_UNAVAILABLE</code> warning</td></tr><tr><td>Bitcoin shorting (execution via <code>hyperliquid trade --side sell</code>)</td><td><strong>LIVE (execution)</strong> / ANALYSIS (signals)</td><td>Short execution is the same signed EIP-712 path as any Hyperliquid order. <code>short signal</code> is read-only OBI/microprice/VPIN research over supplied data — never an execution trigger</td></tr><tr><td>Escrow (<code>furlpay escrow</code>)</td><td>LOCAL LEDGER</td><td>Deterministic state machine + audit log at <code>~/.furlpay/escrows.json</code>; fund/release require real <code>--tx-hash</code> (never fabricated); cryptographic seller-signature proof verification; no on-chain contract deployed</td></tr><tr><td>Streaming engine (<code>L2DeltaBook</code> / <code>RollingVpin</code> / <code>WsConnectionManager</code>)</td><td>IMPLEMENTED (state machines, transport-agnostic)</td><td>Sequence-gap poisoning forces REST resync; rolling VPIN emits on bucket completion; exponential backoff + heartbeat staleness + subscription dedup/cap. Wire a real socket into <code>connect()</code> to go live</td></tr><tr><td>Binance spot adapter</td><td>IMPLEMENTED, TESTNET-BLOCKED</td><td>Full unit battery against stubbed transport (14 tests: signing determinism, secret redaction, env separation, error surfacing, gate ordering); live/testnet end-to-end requires API credentials with withdrawals disabled. Exchange errors surface code+message+HTTP status — never a synthetic success</td></tr><tr><td>Sweep artifact utilities (<code>fork simulate</code> / <code>psbt-inspect</code> / <code>opreturn</code> / <code>taint-plan</code>)</td><td>IMPLEMENTED (offline)</td><td>Integer-minor deterministic math, depth+cap refusals; BIP-174 inspector; BIP-62 minimal-push OP_RETURN; all artifacts review-only — never broadcast. Live venue data: NOT IMPLEMENTED</td></tr><tr><td>Market microstructure analytics</td><td>IMPLEMENTED (offline)</td><td>EW-OBI, Stoikov microprice, Easley-VPIN, Avellaneda-Stoikov quotes — pure math over supplied snapshots/tapes</td></tr><tr><td>Fork operations (<code>fork networks/inspect/replay-check</code>)</td><td>IMPLEMENTED (read-only)</td><td>Offline replay-risk audit + declared registry (BTCB2, BTC1, ECX — unverified declarations). Phase-3 surfaces refuse with <code>NOT_IMPLEMENTED</code> — nothing simulated</td></tr><tr><td>x402 settlement (<code>x402 pay</code>, MCP <code>furlpay_settle_invoice</code>)</td><td><strong>SIMULATED</strong></td><td>No live TigerBeetle facilitator in this build; responses say <code>SIMULATED</code> / <code>LOCAL_SIMULATION</code></td></tr><tr><td>Stellar SDEX order flow / SEP-8 KYC / Soroban swaps</td><td><strong>SIMULATED</strong></td><td>Deterministic local simulation of Horizon/Soroban submission — no network transactions broadcast. <code>rwa kyc</code> reports <code>NOT_IMPLEMENTED</code> (exit 1); regulated-asset trade results carry <code>sep8Status: &quot;not_performed&quot;</code> — compliance never claimed. Registry carries no hardcoded APY and no invented approval-server URLs</td></tr><tr><td>MCP <code>furlpay_balance</code> (unauthenticated mode)</td><td><strong>SIMULATED</strong></td><td>Sample fixture balances, flagged <code>simulated: true</code></td></tr><tr><td>FOBXX sweep (<code>furlpay_sweep_treasury</code> target FOBXX)</td><td><strong>SIMULATED</strong></td><td>No Stellar Benji contract call in this build; APY is <code>null</code> with an explanatory note</td></tr><tr><td>Mainnet readiness gate (<code>furlpay mainnet readiness/status/dry-run</code>)</td><td><strong>LIVE</strong> (read-only gate)</td><td>13 prerequisite checks with evidence and a hard verdict (exit 1 = not-ready). The dry run pushes a hypothetical order through the REAL risk engine against live mainnet data and can never sign or submit — only <code>/info</code> is reachable from a dry run, pinned by test. Stage D real-money execution requires the operator&#39;s explicit transaction-specific confirmation per order (<code>MAINNET_TESTING_RUNBOOK.md</code>).</td></tr><tr><td>Oracle quotes (<code>furlpay oracle</code>, MCP <code>furlpay_oracle_price</code>)</td><td><strong>LIVE</strong> (read-only)</td><td>Multi-source USD fan-out (Coinbase, Kraken, Binance USDT-cross, Jupiter) with per-asset sanity bands and a cross-source agreement gate. DISAGREEMENT → per-source readings + <strong>null price</strong> (never blended); UNAVAILABLE → nothing guessed. Pyth Hermes provider inactive unless a gateway + feed ids are configured.</td></tr><tr><td>Solana live surface (<code>furlpay solana status/balance/price/quote</code>)</td><td><strong>LIVE</strong> (read-only)</td><td>Real RPC reads + indicative Jupiter routes. Addresses base58-validated pre-request; RPC errors throw (no synthetic slots). No Solana signing path exists in this build — quotes are <code>INDICATIVE</code> only.</td></tr></tbody></table><h2 id="environment-key-honesty" tabindex="-1">Environment-key honesty <a class="header-anchor" href="#environment-key-honesty" aria-label="Permalink to &quot;Environment-key honesty&quot;">​</a></h2><p>HLP/perp execution reads <code>HYPERLIQUID_PRIVATE_KEY</code> (or <code>ETH_PRIVATE_KEY</code>) from the environment — never from argv. Private keys and mnemonics for <code>wallet import</code> / <code>login --key</code> are accepted on stdin only.</p>',5)])])}const g=t(a,[["render",n]]);export{h as __pageData,g as default};
